#include <iostream>
using namespace std;

long long int mod_pow(long long int a, long long int b) {
    long long int mod = 1000000007;
    long long int res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

long long int order(long long int k, long long int p) {
    long long int x = k;
    long long int ord = 1;
    while (x != 1) {
        x = (x * k) % p;
        ord++;
    }
    return ord;
}

int main() {
    long long int p, k;
    cin >> p >> k;
    long long int power;
    if (k == 0) {
        power = p - 1;
    } else if (k == 1) {
        power = p;
    } else {
        long long int ord = order(k, p);
        power = (p - 1) / ord;
    }
    cout << mod_pow(p, power) << endl;
    return 0;
}
